snippet_css:
:root{
  --bg: #0D0221;
  --fg: #F9F1FF;
  --muted: #C9A0FF;
  --surface: rgba(255,255,255,.08);
  --border: rgba(255,46,151,.45);
  --accent: #FF2E97;
  --accent-fg: #0D0221;
  --radius: 2px;
  --radius-sm: 2px;
  --shadow: 0 0 0 1px rgba(255,46,151,.35),0 0 30px rgba(255,46,151,.22);
  --btn-shadow: 0 0 18px rgba(0,240,255,.45);
  --art-bg: linear-gradient(180deg,#0D0221 0%,#2B0F54 40%,#AB1F65 72%,#0D0221 72.2%);
  --media-bg: linear-gradient(180deg,#F9F871,#FF8C42 45%,#FF2E97 80%);
  --cta-bg: rgba(0,240,255,.10);
  --input-bg: #150430;
  --ok: #3CF2B4;
  --warn: #F9F871;
  --font-display: Orbitron,'Noto Sans TC',sans-serif;
  --font-body: Rajdhani,'Noto Sans TC',sans-serif;
  --font-mono: Orbitron,ui-monospace,monospace;
  --focus-ring: var(--accent);
}

